 string Value(string key)=>fields[key].Text?.Trim()??"";
 string FindHome(){if(Directory.Exists(Path.Combine(LocalStorage.Home,"scripts")))return LocalStorage.Home;var portable=Environment.GetEnvironmentVariable("SCT_HOME");if(!string.IsNullOrWhiteSpace(portable)&&Directory.Exists(Path.Combine(portable,"scripts")))return Path.GetFullPath(portable);var d=new DirectoryInfo(AppContext.BaseDirectory);while(d!=null){if(Directory.Exists(Path.Combine(d.FullName,"scripts"))&&Directory.Exists(Path.Combine(d.FullName,"src")))return d.FullName;d=d.Parent;}return AppContext.BaseDirectory;}
 string Worker(){var p=Path.Combine(home,"runtime/worker/CharacterWorker.exe");return File.Exists(p)?p:Path.Combine(home,"src/CharacterWorker/bin/Release/net9.0-windows/CharacterWorker.exe");}
 void Log(string s)=>AppendLog(s);
 void SaveSettings(){if(args.Contains("--e2e-navigation"))return;Directory.CreateDirectory(Path.GetDirectoryName(config)!);var settings=fields.ToDictionary(x=>x.Key,x=>x.Value.Text);foreach(var key in new[]{"output","cache"}){var path=Value(key);if(Path.IsPathRooted(path)){var rel=Path.GetRelativePath(home,path);if(rel!=".."&&!rel.StartsWith(".."+Path.DirectorySeparatorChar)&&!Path.IsPathRooted(rel))settings[key]=rel;}}settings["npc_weapon_mode"]=NpcWeaponMode;settings["action_disk_cache"]=actionDiskCache.IsChecked==true?"true":"false";settings["auto_clear_cache"]=autoClearCache.IsChecked==true?"true":"false";settings["blend_output_mode"]=UseBatches?"batches":"single";settings["batch_build"]=UseBatches?"true":"false";settings["batch_size"]=batchSize.Text;settings["show_helpers"]=showHelpers.IsChecked==true?"true":"false";settings["restore_hierarchy"]=restoreHierarchy.IsChecked==true?"true":"false";settings["clean_bones"]=cleanBones.IsChecked==true?"true":"false";settings["root_axes"]=RootAxes();settings["append_target"]=appendTarget.SelectedIndex==1?"cs2":"blend";SaveCs2(settings);File.WriteAllText(config,JsonSerializer.Serialize(settings,new JsonSerializerOptions{WriteIndented=true}));}
 async Task Run(Func<Task> task){if(busy)return;bool taskSucceeded=false;busy=true;runLog=Path.Combine(Value("cache"),"logs",DateTime.Now.ToString("yyyyMMdd_HHmmss_fff")+".log");page.IsEnabled=false;if(navigation!=null)navigation.IsEnabled=false;cancel=new();progress.IsIndeterminate=true;failureDetail=null;ToolTip.SetTip(status,null);logs.Text="";status.Text="执行中…";try{Directory.CreateDirectory(Path.GetDirectoryName(runLog)!);BeginTaskStorage();SaveSettings();await task();taskSucceeded=true;if(status.Text=="执行中…")status.Text="任务完成 · 详见输出报告";}catch(OperationCanceledException){status.Text="已取消 · 部分输出保留，重新导出会使用新目录";Log("CANCELLED");}catch(Exception e){SetFailure(e);}finally{FinishTaskStorage(taskSucceeded);busy=false;page.IsEnabled=true;if(navigation!=null)navigation.IsEnabled=true;progress.IsIndeterminate=false;cancel.Dispose();cancel=null;}}
 async Task Exec(string exe,params string[] argv){cancel!.Token.ThrowIfCancellationRequested();if(!File.Exists(exe))throw new FileNotFoundException("未找到工具",exe);var info=new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=home};LocalStorage.Apply(info,activeTaskCache??Value("cache"));info.StandardOutputEncoding=System.Text.Encoding.UTF8;info.StandardErrorEncoding=System.Text.Encoding.UTF8;foreach(var s in argv){if(s=="--python"&&Path.GetFileName(exe).Equals("blender.exe",StringComparison.OrdinalIgnoreCase)){info.ArgumentList.Add("--python");info.ArgumentList.Add(Path.Combine(home,"scripts","blender_bootstrap.py"));}info.ArgumentList.Add(s);}Log(Path.GetFileName(exe)+" "+string.Join(" ",argv));string? errorDetail=null;bool memoryFailure=false;using var p=new Process{StartInfo=info};p.Start();using var reg=cancel.Token.Register(()=>{try{if(!p.HasExited)p.Kill(true);}catch{}});async Task Pump(StreamReader r){string? s;while((s=await r.ReadLineAsync())!=null){Log(s);if(s.Contains("MemoryError")||s.Contains("Malloc returns null")||s.Contains("Unable to allocate")||s.Contains("SCT_MEMORY"))memoryFailure=true;if(s.Contains("Error:")||s.Contains("Exception:")||s.Contains("空间不足"))errorDetail=s;}}await Task.WhenAll(Pump(p.StandardOutput),Pump(p.StandardError),p.WaitForExitAsync());cancel.Token.ThrowIfCancellationRequested();if(p.ExitCode!=0)throw new Exception((memoryFailure?"系统可提交内存不足；开启低内存分批（1–8 动作），关闭占用大量内存的 CS2/模拟器，再点“继续已有提取包”。已完成批次保留。":errorDetail??Path.GetFileName(exe)+" 退出码 "+p.ExitCode)+"；完整日志："+runLog);}
 string Cache(string name){var p=Path.Combine(Value("cache"),name);Directory.CreateDirectory(Path.GetDirectoryName(p)!);return p;}
 async Task Scan(){await Exec(Worker(),"scan","--root",Value("game"),"--out",Cache("scan.json"));var j=JsonNode.Parse(File.ReadAllText(Cache("scan.json")))!;ids=j["characters"]!.AsArray().Select(x=>x!["id"]!.ToString()).ToArray();animation.ItemsSource=ids;Filter();await Exec(Worker(),"weapons","--root",Value("game"),"--out",Cache("weapons.json"));partIds=JsonNode.Parse(File.ReadAllText(Cache("weapons.json")))!["weapons"]!.AsArray().Select(x=>x!["id"]!.ToString()).ToArray();weapons.ItemsSource=partIds;await Exec(Worker(),"params","--root",Value("game"),"--out",Path.GetDirectoryName(Cache("params.json"))!);prosthetic.ItemsSource=JsonNode.Parse(File.ReadAllText(Cache("EquipParamWeapon.param.json")))!.AsArray().Where(x=>x!["id"]!.GetValue<int>()>=70000&&x["id"]!.GetValue<int>()<80000).Select(x=>x!["id"]+" · "+x["name"]).ToArray();Log($"发现 {ids.Length} 个角色 / {partIds.Length} 个武器部件包");}
 void Filter(){var s=search.Text??"";characters.ItemsSource=ids.Where(x=>x.Contains(s,StringComparison.OrdinalIgnoreCase)).ToArray();}
