 async Task Analyze(){var id=Selected();await Exec(Worker(),"analyze","--root",Value("game"),"--character",id,"--animation",animation.SelectedItem as string??id,"--out",Cache("analysis.json"));var j=JsonNode.Parse(File.ReadAllText(Cache("analysis.json")))!;details.Text=$"角色 {id} / 动画来源 {j["animationSource"]}\n模型 {j["models"]} · 网格 {j["meshes"]} · 顶点 {j["vertices"]} · FLVER 骨 {j["bones"]}\n动画包 {j["animationPackages"]} · HKX {j["hkx"]} · TAE {j["tae"]}\n\n"+string.Join("\n",j["notes"]!.AsArray().Select(x=>x!.GetValue<string>()))+"\n\n完整条目清单："+Cache("analysis.json");}
